39|     /**
40|      * Get a Tag by name. If not previously defined (unknown), returns a new generic tag, that can do anything.
41|      * <p>
42|      * Pre-defined tags (P, DIV etc) will be ==, but unknown tags are not registered and will only .equals().
43|      * </p>
44|      * 
45|      * @param tagName Name of tag, e.g. "p". Case insensitive.
46|      * @param settings used to control tag name sensitivity
47|      * @return The tag, either defined or new generic.
48|      */
49|     public static Tag valueOf(String tagName, ParseSettings settings) {
50|         Validate.notNull(tagName);
51|         Tag tag = tags.get(tagName);
52| 
53|         if (tag == null) {
54|             tagName = settings.normalizeTag(tagName);
55|             Validate.notEmpty(tagName);
56|             tag = tags.get(tagName);
57| 
58|             if (tag == null) {
59|                 // not defined: create default; go anywhere, do anything! (incl be inside a <p>)
60|                 tag = new Tag(tagName);
61|                 tag.isBlock = false;
62|             }
63|         }
64|         return tag;
65|     }
