29|     protected void initialiseParse(Reader input, String baseUri, ParseErrorList errors, ParseSettings settings) {
30|         Validate.notNull(input, "String input must not be null");
31|         Validate.notNull(baseUri, "BaseURI must not be null");
32| 
33|         doc = new Document(baseUri);
34|         this.settings = settings;
35|         reader = new CharacterReader(input);
36|         this.errors = errors;
37|         currentToken = null;
38|         tokeniser = new Tokeniser(reader, errors);
39|         stack = new ArrayList<>(32);
40|         this.baseUri = baseUri;
41|     }
