69|     public boolean processStartTag(String name, Attributes attrs) {
70|         if (currentToken == start) { // don't recycle an in-use token
71|             return process(new Token.StartTag().nameAttr(name, attrs));
72|         }
73|         start.reset();
74|         start.nameAttr(name, attrs);
75|         return process(start);
76|     }
